"""
assets/icon.py – Programmatically embedded icon (red→purple gradient, download arrow).
No external files needed.
"""
import base64, io, struct, zlib


_PNG_256_B64 = ""
_ICO_B64     = ""


def get_icon_png_bytes() -> bytes:
    """Return 256×256 RGBA PNG bytes."""
    return base64.b64decode(_PNG_256_B64)


def get_icon_b64() -> str:
    """Return PNG as base64 string (for tk PhotoImage data=)."""
    return _PNG_256_B64


def get_icon_ico_bytes() -> bytes:
    """Return .ico file bytes (for PyInstaller --icon or taskbar)."""
    return base64.b64decode(_ICO_B64)


def save_ico(path: str) -> str:
    """Write the .ico to disk and return the path (used by build scripts)."""
    import os, tempfile
    if path is None:
        fd, path = tempfile.mkstemp(suffix=".ico")
        os.close(fd)
    with open(path, "wb") as f:
        f.write(get_icon_ico_bytes())
    return path


if __name__ == "__main__":
    with open("icon_preview.png","wb") as f: f.write(get_icon_png_bytes())
    with open("icon_preview.ico","wb") as f: f.write(get_icon_ico_bytes())
    print("Saved icon_preview.png and icon_preview.ico")
